from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]; T=ROOT/'theme'
def write(name,content):
 p=T/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(content.strip()+'\n')
def js(name,obj):write(name,json.dumps(obj,indent=2))
def section(name,markup,schema):write('sections/'+name+'.liquid',markup+'\n{% schema %}\n'+json.dumps(schema,indent=2)+'\n{% endschema %}')
def setting(t,id,label,default=None,**kw):
 d={'type':t,'id':id,'label':label,**kw}
 if default is not None:d['default']=default
 return d
write('layout/theme.liquid','''<!doctype html>
<html lang="{{ request.locale.iso_code }}">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="theme-color" content="{{ settings.color_background }}">
<link rel="canonical" href="{{ canonical_url }}">
<title>{{ page_title }}{% if current_tags %} – {{ current_tags | join: ', ' }}{% endif %}{% if current_page != 1 %} – {{ current_page }}{% endif %}{% unless page_title contains shop.name %} – {{ shop.name }}{% endunless %}</title>
{% if page_description %}<meta name="description" content="{{ page_description | escape }}">{% endif %}
<meta property="og:site_name" content="{{ shop.name | escape }}"><meta property="og:url" content="{{ canonical_url }}"><meta property="og:title" content="{{ page_title | escape }}"><meta property="og:description" content="{{ page_description | default: shop.description | escape }}"><meta property="og:type" content="{% if template.name == 'product' %}product{% else %}website{% endif %}">
{% if page_image %}<meta property="og:image" content="https:{{ page_image | image_url: width: 1200 }}">{% endif %}
{% if settings.favicon != blank %}<link rel="icon" href="{{ settings.favicon | image_url: width: 32 }}">{% endif %}
{{ content_for_header }}
{% render 'theme-styles' %}
{% render 'commerce-styles' %}
</head>
<body class="template-{{ template.name }}{% if template.name == 'index' and settings.transparent_header %} has-transparent-header{% endif %}">
<a class="skip-link" href="#MainContent">{{ 'general.skip' | t }}</a>
{% sections 'header-group' %}
<main id="MainContent" tabindex="-1">{{ content_for_layout }}</main>
{% sections 'footer-group' %}
{% render 'cart-drawer' %}
{% render 'theme-script' %}
{% render 'commerce-script' %}
</body></html>''')
