section('contact-form','''<section class="content-page"><h1>{{ section.settings.heading | escape }}</h1><div class="rte">{{ section.settings.text }}</div>{% form 'contact' %}{% if form.posted_successfully? %}<p role="status">{{ 'contact.success' | t }}</p>{% else %}{{ form.errors | default_errors }}<div class="contact-grid"><label for="ContactName">{{ 'contact.name' | t }}<input id="ContactName" name="contact[name]" autocomplete="name" value="{{ form.name | escape }}" required></label><label for="ContactEmail">{{ 'contact.email' | t }}<input id="ContactEmail" type="email" name="contact[email]" autocomplete="email" value="{{ form.email | escape }}" required></label><label class="full" for="ContactMessage">{{ 'contact.message' | t }}<textarea id="ContactMessage" name="contact[body]" required>{{ form.body | escape }}</textarea></label><button class="button full" type="submit">{{ 'contact.send' | t }}</button></div>{% endif %}{% endform %}</section>''',{'name':'Contact form','settings':[setting('text','heading','Heading','Client Services'),setting('richtext','text','Introduction','<p>For help choosing a piece, an order update, or a question about your bag, leave us a note.</p>')],'presets':[{'name':'Contact form'}]})
section('main-blog','''<section class="page-width section-space"><div class="editorial-text section-space"><h1>{{ blog.title | escape }}</h1></div>{% paginate blog.articles by 12 %}<div class="blog-grid">{% for article in blog.articles %}<article>{% if article.image %}<a href="{{ article.url }}">{{ article.image | image_url: width: 900 | image_tag: loading: 'lazy' }}</a>{% endif %}<p class="micro">{{ article.published_at | date: format: 'date' }}</p><h2><a href="{{ article.url }}">{{ article.title | escape }}</a></h2><p>{{ article.excerpt_or_content | strip_html | truncate: 160 }}</p><a class="text-link" href="{{ article.url }}">{{ 'general.read_more' | t }}</a></article>{% endfor %}</div>{{ paginate | default_pagination }}{% endpaginate %}</section>''',{'name':'Journal','settings':[]})
section('main-article','''<article class="content-page"><p class="eyebrow">{{ article.published_at | date: format: 'date' }}</p><h1>{{ article.title | escape }}</h1>{% if article.image %}{{ article.image | image_url: width: 1400 | image_tag: class: 'article-hero', loading: 'eager' }}{% endif %}<div class="rte">{{ article.content }}</div><a class="text-link" href="{{ blog.url }}">{{ 'general.back_journal' | t }}</a></article>''',{'name':'Article','settings':[]})
section('main-list-collections','''<section class="page-width section-space"><div class="editorial-text section-space"><h1>{{ 'general.collection' | t }}</h1></div>{% paginate collections by 24 %}<div class="blog-grid">{% for collection in collections %}<article><a href="{{ collection.url }}">{% if collection.featured_image %}{{ collection.featured_image | image_url: width: 900 | image_tag: loading: 'lazy' }}{% endif %}<h2>{{ collection.title | escape }}</h2><p class="micro">{{ collection.all_products_count }} {{ 'general.pieces' | t }}</p></a></article>{% endfor %}</div>{{ paginate | default_pagination }}{% endpaginate %}</section>''',{'name':'Collections','settings':[]})
section('main-404','''<section class="empty-state"><p class="eyebrow">404</p><h1>{{ 'general.not_found' | t }}</h1><p>{{ 'general.not_found_text' | t }}</p><a class="button" href="{{ routes.all_products_collection_url }}">{{ 'general.view_collection' | t }}</a></section>''',{'name':'Page not found','settings':[]})
section('custom-liquid','''<section class="page-width">{{ section.settings.custom_liquid }}{% for block in section.blocks %}{% render block %}{% endfor %}</section>''',{'name':'Custom Liquid and apps','settings':[setting('liquid','custom_liquid','Custom Liquid')],'blocks':[{'type':'@app'}],'presets':[{'name':'Custom Liquid and apps'}]})
